                        return err
                }
        }
        return nil
}

func unitSource(pkg, id string, slots []string) string {
        quoted := make([]string, 0, len(slots))
        for _, s := range slots {
                quoted = append(quoted, `"`+s+`"`)
        }
        return "package " + pkg + "\n\nimport \"loft.local/lanternix/packbay/store\"\n\nfunc Load() {\n\tstore.Offer(\"" + id + "\", store.Spec{Slots: []string{
" + strings.Join(quoted, ", ") + "}})\n}\n"
